package my_programs;

public class Relation_Operators {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int x = 2, y = 6;  
		
		System.out.println(x ==y);
		System.out.println(x!=y);
		System.out.println(x>y);
		System.out.println(x<y);
		System.out.println(x >=5 );
		System.out.println(y<=10);
		
	}

}
